<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS); const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
<main class="oy-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="oy-opbar"><button @click="emit('back')">←</button><strong>OLIVE YOUNG</strong><div><button data-testid="shopping-open-service" @click="emit('open-service')">CARE</button><button @click="emit('open-orders')">RESTOCKS</button><button @click="emit('open-cart')"><i class="fas fa-bag-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>
    <section v-if="pageKey==='cart'" id="shopping-cart" class="oy-routine"><header><span>ROUTINE BASKET / {{ cartQuantity }} STEPS</span><h1>{{ l('检查步骤，不重复堆叠','Review the steps without stacking duplicates') }}</h1><div><article><b>AM</b><span>{{ Math.ceil(cartQuantity/2) }} ITEMS</span></article><article><b>PM</b><span>{{ Math.floor(cartQuantity/2) }} ITEMS</span></article></div></header><section class="oy-routine-line"><span>01 CLEANSE</span><i></i><span>02 HYDRATE</span><i></i><span>03 BARRIER</span><i></i><span>04 FINISH</span></section><div v-if="!cartItems.length" class="oy-empty">ROUTINE BASKET EMPTY</div><div v-else class="oy-routine-layout"><section><article v-for="(line,index) in cartItems" :key="line.productId"><span class="oy-texture"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i><em>STEP {{ index%4+1 }}</em></span><div><small>{{ index%2?'PM / CREAM':'AM / GEL' }}</small><strong>{{ productDisplayTitle(line.product) }}</strong><p>{{ l('质地与使用顺序在订单中保留','Texture and routine order stay with the order') }}</p><b>{{ formatOrderItemSubtotal({ ...line,unitPriceCents:line.product.priceCents,currency:line.currency }) }}</b><div><button @click="emit('update-quantity',line.productId,-1)">−</button><span>{{ line.quantity }}</span><button @click="emit('update-quantity',line.productId,1)">+</button></div></div></article></section><aside><p>ROUTINE REVIEW</p><strong>{{ cartTotalLabel }}</strong><div class="oy-overlap"><i class="fas fa-layer-group"></i><span>{{ l('功效不作医疗判断；这里只核对步骤与重复类型。','No medical judgment; this review only checks steps and overlapping types.') }}</span></div><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled',$event.target.checked)" />{{ l('护理礼物','Care gift') }}</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId',$event.target.value)"><option value="">{{ l('手动收件人','Manual recipient') }}</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" @input="emit('update:giftRecipientName',$event.target.value)" /><button data-testid="shopping-checkout" @click="emit('checkout')">{{ l('确认护理补货','Confirm routine restock') }}</button></aside></div></section>
